import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百九十四章 从界中解脱出来","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/194第一百九十四章 从界中解脱出来.md","filePath":"meditation/巴利文大藏经/194第一百九十四章 从界中解脱出来.md"}'),_={name:"meditation/巴利文大藏经/194第一百九十四章 从界中解脱出来.md"};function r(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第一百九十四章-从界中解脱出来" tabindex="-1">第一百九十四章 从界中解脱出来 <a class="header-anchor" href="#第一百九十四章-从界中解脱出来" aria-label="Permalink to &quot;第一百九十四章 从界中解脱出来&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部18相应9经/界经(罗侯罗相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，罗侯罗尊者来到佛陀的住所，他顶礼佛陀后，就在一旁坐下，佛陀对罗侯罗尊者说：“罗侯罗！你是怎么想的？地界（地界解释，见第一百二十四章）是永恒存在的，永远保持不变的，还是随时在变化的，无法永恒存在，无法永远保持不变的？</p><p>罗侯罗尊者回答：“世尊，地界是随时都在变化的，是无法永恒存在的，是无法永远保持不变的。”</p><p>佛陀说：“罗侯罗！水界、火界、风界（水界、火界、风界解释，见第一百二十四章）、空界、识界是永恒存在的，永远保持不变的，还是随时在变化的，无法永恒存在，无法永远保持不变的？</p><p>罗侯罗！什么是空界呢？就是能够容纳物质事物的空间、虚空，比如孔洞、裂缝、空地、口腔、咽喉、肚肠等等。</p><p>什么是识界呢？就是眼识、耳识、鼻识、舌识、身识、意识（眼识、耳识、鼻识、舌识、身识、意识解释，见第一百八十八章）。</p><p>罗侯罗尊者回答：“世尊，水界、火界、风界、空界、识界是随时都在变化的，是无法永恒存在的，是无法永远保持不变的。”</p><p>佛陀说：“罗侯罗！已经受到如来教导的圣弟子们，他们将会逐渐的除灭对地界、水界、火界、风界、空界、识界的贪欲，他们不会再执着和挂念地界、水界、火界、风界、空界、识界，他们从地界、水界、火界、风界、空界、识界中解脱出来，他们由此证悟了解脱的智慧，证悟了解脱的果位，他们彻底的明白：「从这一世开始已经不会再次的出生在世间。行为、言语、念想的修行已经圆满，应该做的事情已经做好，不会再有轮回的状态，不会再出生在世间了」。”</p><p>佛陀说法后，罗侯罗尊者再次的顶礼佛陀，他随喜赞叹佛陀说法的无量功德，并按着佛陀所说的法去修行。</p>',11)]))}const f=e(_,[["render",r]]);export{m as __pageData,f as default};
